try {
  const headers = $input.first().json.headers || {};
  const token = headers['x-pmo-token'] || headers['X-PMO-Token'] || '';
  const secret = 'change-me-pmo-secret-2026';
  if (token !== secret) {
    return [{ json: { status: 'failed', message: 'توکن نامعتبر' } }];
  }
  const body = $input.first().json.body || $input.first().json;
  const payload = {
    contractor_name: body.contractor_name || '',
    delay_subject: body.delay_subject || body.subject || '',
    extra_context: body.extra_context || '',
    free_prompt: body.free_prompt || '',
  };
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://lmstudio-gateway:8081/api/pmo/letter',
    headers: {
      'X-PMO-Token': secret,
      'Content-Type': 'application/json',
    },
    body: payload,
    json: true,
    timeout: 900000,
    ignoreHttpStatusErrors: true,
  });
  return [{ json: response }];
} catch (e) {
  return [{ json: { status: 'failed', message: e.message || String(e) } }];
}
